import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:intl/date_symbol_data_local.dart';
import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';
import 'package:mockito/mockito.dart';

import '../mocks/repository.mocks.dart';

import 'widget.dart';

Future<void> main() async {
  await initializeDateFormatting(AppConstants.ruLocale, null);

  testWidgets('probe', (WidgetTester tester) async {
    final MockNewsRepository mockNewsRepository = MockNewsRepository();

    final cachedNewsItems = [
      NewsModel(title: 'Из кэша 1', link: 'https://example.com/cached/1', date: DateTime.now()),
    ];
    final freshNewsItems = [
      NewsModel(title: 'Свежая 1', link: 'https://example.com/fresh/1', date: DateTime.now()),
    ];

    final Completer<List<NewsModel>> network = Completer<List<NewsModel>>();
    when(mockNewsRepository.loadNewsFeed(any)).thenAnswer((_) async => freshNewsItems);
    when(mockNewsRepository.loadNewsFeed(NewsFeedFilter.all)).thenAnswer((_) async => cachedNewsItems);
    when(mockNewsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true))).thenAnswer((_) => network.future);

    await tester.pumpWidget(
      buildWidget(
        providers: [
          Provider<NewsRepository>.value(value: mockNewsRepository),
        ],
        child: const NewsListPage(),
      ),
    );

    await tester.pump();
    debugPrint('before network: cached1=${find.text('Из кэша 1').evaluate().length} fresh1=${find.text('Свежая 1').evaluate().length}');

    network.complete(freshNewsItems);
    await tester.pump();
    await tester.pumpAndSettle();
    debugPrint('after network: cached1=${find.text('Из кэша 1').evaluate().length} fresh1=${find.text('Свежая 1').evaluate().length}');
