import 'package:flutter_test/flutter_test.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';
import 'package:mockito/mockito.dart';

import '../mocks/repository.mocks.dart';

void main() {
  test('probe matchers', () async {
    final MockNewsRepository mock = MockNewsRepository();
    final List<NewsModel> items = [
      NewsModel(title: 'x', link: 'https://example.com/x', date: DateTime.now()),
    ];
    final Completer<List<NewsModel>> completer = Completer<List<NewsModel>>();

    when(mock.loadNewsFeed(any)).thenAnswer((_) async => items);
    when(mock.loadNewsFeed(const NewsFeedFilter(forceRefresh: true))).thenAnswer((_) => completer.future);
    when(mock.loadNewsFeed(NewsFeedFilter.all)).thenAnswer((_) async => items);

    unawaited(mock.loadNewsFeed(NewsFeedFilter.all));
    unawaited(mock.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)));
    await Future<void>.delayed(Duration.zero);

    final argThat cacheMatcher =
        argThat(isA<NewsFeedFilter>().having((f) => f.forceRefresh, 'forceRefresh', isFalse));
    final argThat freshMatcher =
        argThat(isA<NewsFeedFilter>().having((f) => f.forceRefresh, 'forceRefresh', isTrue));

    // ignore: avoid_print
    print('cache matches: ${verify(mock.loadNewsFeed(cacheMatcher)).callCount}');
    // ignore: avoid_print
    print('fresh matches: ${verify(mock.loadNewsFeed(freshMatcher)).callCount}');
  });
}
