Future<void> main() async {
  await initializeDateFormatting(AppConstants.ruLocale, null);

  group('NewsListPage', () {
    final MockNewsRepository mockNewsRepository = MockNewsRepository();

    final cachedNewsItems = [
      NewsModel(title: 'Из кэша 1', link: 'https://example.com/cached/1', date: DateTime.now()),
      NewsModel(title: 'Из кэша 2', link: 'https://example.com/cached/2', date: DateTime.now()),
    ];

    final freshNewsItems = [
      NewsModel(title: 'Свежая 1', link: 'https://example.com/fresh/1', date: DateTime.now()),
      NewsModel(title: 'Свежая 2', link: 'https://example.com/fresh/2', date: DateTime.now()),
      NewsModel(title: 'Свежая 3', link: 'https://example.com/fresh/3', date: DateTime.now()),
    ];

    setUp(() {
      when(mockNewsRepository.loadNewsFeed(NewsFeedFilter.all)).thenAnswer((_) async => cachedNewsItems);
      when(mockNewsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true))).thenAnswer((_) async => freshNewsItems);
      when(mockNewsRepository.saveNewsList(any)).thenAnswer((_) async {});
    });

    testWidgets('should display all news items when loaded', (WidgetTester tester) async {
      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<NewsRepository>.value(value: mockNewsRepository),
          ],
          child: const NewsListPage(),
        ),
      );

      await tester.pumpAndSettle();

      expect(find.text('Свежая 1'), findsOneWidget);
      expect(find.text('Свежая 2'), findsOneWidget);
      expect(find.text('Свежая 3'), findsOneWidget);
      expect(find.text('Из кэша 1'), findsNothing);
    });

    testWidgets('should show cached news first and then refresh from network', (WidgetTester tester) async {
      final Completer<List<NewsModel>> networkResponse = Completer<List<NewsModel>>();
      when(mockNewsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)))
          .thenAnswer((_) => networkResponse.future);

      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<NewsRepository>.value(value: mockNewsRepository),
          ],
          child: const NewsListPage(),
        ),
      );

      // Кэш показывается до завершения сетевого запроса.
      await tester.pump();
      expect(find.text('Из кэша 1'), findsOneWidget);
      expect(find.text('Из кэша 2'), findsOneWidget);
      expect(find.text('Свежая 1'), findsNothing);

      // По приходу ответа сети список обновляется.
      networkResponse.complete(freshNewsItems);
      await tester.pump();
      await tester.pumpAndSettle();

      expect(find.text('Свежая 1'), findsOneWidget);
      expect(find.text('Свежая 2'), findsOneWidget);
      expect(find.text('Свежая 3'), findsOneWidget);
      expect(find.text('Из кэша 1'), findsNothing);
      expect(find.text('Из кэша 2'), findsNothing);

      // Кэш читается без forceRefresh, сеть — только с forceRefresh.
      verify(mockNewsRepository.loadNewsFeed(argThat(isA<NewsFeedFilter>().having((NewsFeedFilter f) => f.forceRefresh, 'forceRefresh', isFalse))))
          .called(1);
      verify(mockNewsRepository.loadNewsFeed(argThat(isA<NewsFeedFilter>().having((NewsFeedFilter f) => f.forceRefresh, 'forceRefresh', isTrue))))
          .called(1);
    });
  });
}

